// Arma el mensaje de WhatsApp según el tipo (dm o content)
const input = $input.first().json;
let text;
if (input.type === 'dm') {
  text = `🔔 *Nuevo DM para aprobar*

Lead: ${input.payload.source_handle} (${input.payload.source_platform})
Comentario original: "${input.payload.source_comment_text}"

Borrador de respuesta:
"${input.payload.draft_message}"

Responde: APROBAR / RECHAZAR / o escribe el texto corregido.`;
} else {
  text = `🎬 *Contenido listo para revisar* (${input.payload.slot})

Caption: "${input.payload.caption}"
Plataformas: ${input.payload.target_platforms.join(', ')}
Colab MiniTrucks: ${input.payload.collab_with_minitrucks ? 'Sí' : 'No'}

Video/foto adjunto abajo.

Responde: APROBAR / RECHAZAR / o describe el cambio que quieres.`;
}
return [{ json: { ...input, whatsapp_text: text } }];

// Interpreta la respuesta de Santiago: APROBAR, RECHAZAR, o texto = edición
const body = $input.first().json.body;
const msg = (body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.text?.body || '').trim();
const upper = msg.toUpperCase();
let result;
if (upper === 'APROBAR' || upper === 'APRUEBO' || upper === 'SI') {
  result = { approved: true, edited_text: null };
} else if (upper === 'RECHAZAR' || upper === 'NO') {
  result = { approved: false, edited_text: null };
} else if (msg.length > 0) {
  result = { approved: true, edited_text: msg }; // se interpreta como corrección aprobada
} else {
  result = { approved: false, edited_text: null };
}
return [{ json: result }];
